import {initialMarshmallow,stepMarshmallow,marshmallowResult} from './model.js';import {createMarshmallowView,browningColor} from './view.js';import {PLAZA} from '../plaza/layout.js';
export const MARSHMALLOW_BODY=`<header class="marsh-heading"><strong>모닥불 · 마시멜로</strong><button data-marsh-close aria-label="마시멜로 굽기 나가기">나가기 ×</button></header><div class="marsh-court" data-marsh-court tabindex="0" role="img" aria-label="모닥불 옆에서 꼬치를 든 도름이와 마시멜로"></div><section class="marsh-panel" aria-label="마시멜로 굽기 조작"><p class="marsh-status" data-marsh-status role="status" aria-live="polite"></p><div class="marsh-sides" aria-label="마시멜로 네 면의 굽기"><span data-marsh-side="0"></span><span data-marsh-side="1"></span><span data-marsh-side="2"></span><span data-marsh-side="3"></span><small>네 면이 노릇해지면 꺼내요</small></div><label class="marsh-distance"><span>불 가까이</span><input data-marsh-distance type="range" min="0" max="100" value="45" aria-label="불과의 거리. 왼쪽은 가까이, 오른쪽은 멀리"><span>멀리</span></label><div class="marsh-actions"><button data-marsh-rotate aria-pressed="false">꾹 눌러 돌리기 ↻</button><button data-marsh-main>굽기 시작</button><button data-marsh-pause aria-label="굽기 잠깐 쉬기">쉬기</button><button data-marsh-return hidden>조금 더 굽기</button></div><p class="marsh-help" data-marsh-help></p></section>`;
export function createMarshmallowController({stage,ui={toast(){}},getView,getActors,getRoom,reduced=false,onActive=()=>{},isAllowed=()=>true,doc=globalThis.document,win=globalThis.window,createView=createMarshmallowView}={}){
 let live=null;const listen=(s,node,type,fn,options)=>{node?.addEventListener(type,fn,options);s.listeners.push([node,type,fn,options]);};
 function clear(s){s.rotating=false;s.pointer=null;s.key=null;}
 function render(s){if(live!==s)return;const $=q=>s.root.querySelector(q),a=s.state,p=a.phase,result=marshmallowResult(a),roasting=p==='roasting',main=$('[data-marsh-main]'),rotate=$('[data-marsh-rotate]');
 const max=Math.max(...a.browning),min=Math.min(...a.browning);let text=s.paused?'잠깐 쉬는 중 · 계속하기를 누르면 이어져요':p==='ready'?'거리와 돌리기로 골고루 노릇하게 구워요':p==='withdrawing'?'불에서 살며시 꺼내는 중':p==='readyToEat'?`${result.label} · 한 입 먹어 볼까요?`:p==='eating'?'냠! 모닥불 옆의 작은 간식':p==='done'?result.label:max>=1.02?'진한 갈색! 타기 전에 불에서 꺼내요':min>=.48&&max<=.94?'네 면이 노릇노릇 · 지금 꺼내도 좋아요':max-min>.35?'한쪽이 먼저 익어요 · 꼬치를 돌려 주세요':a.distance<.22?'불 가까이 · 금방 진해지니 살펴봐요':a.distance>.75?'불에서 멀리 · 천천히 익고 있어요':'천천히 돌리며 마시멜로 색을 살펴봐요';
 if(s.status!==text){$('[data-marsh-status]').textContent=text;s.status=text;}
 main.textContent=s.paused?'계속하기':p==='ready'?'굽기 시작':roasting?'불에서 꺼내기':p==='readyToEat'?'한 입 먹기':p==='done'?'하나 더 굽기':p==='eating'?'냠냠…':'꺼내는 중…';main.disabled=!s.paused&&['withdrawing','eating'].includes(p);rotate.disabled=s.paused||!roasting;rotate.setAttribute('aria-pressed',String(s.rotating));rotate.textContent=s.rotating?'빙글빙글 ↻':'꾹 눌러 돌리기 ↻';$('[data-marsh-distance]').disabled=s.paused||!['ready','roasting'].includes(p);$('[data-marsh-distance]').value=String(Math.round(a.distance*100));$('[data-marsh-distance]').setAttribute('aria-valuetext',a.distance<.22?'가까이, 빠르게 익어요':a.distance>.75?'멀리, 천천히 익어요':'중간 거리');$('[data-marsh-pause]').hidden=['ready','done'].includes(p);$('[data-marsh-pause]').disabled=s.paused;$('[data-marsh-return]').hidden=p!=='readyToEat';$('[data-marsh-return]').disabled=s.paused;
 for(let i=0;i<4;i++){const node=$(`[data-marsh-side="${i}"]`),b=a.browning[i],label=b>=1.05?'진한 갈색':b>=.48?'노릇':b>.17?'연한 금빛':'하얀색';node.style.backgroundColor='#'+browningColor(b).getHexString();node.textContent=String(i+1);node.setAttribute('aria-label',`${i+1}번 면: ${label}`);node.dataset.tone=b>=1.05?'dark':b>=.48?'golden':'pale';}
 $('[data-marsh-help]').textContent=p==='done'?result.hint:roasting?'거리 조절 · 꾹 눌러 돌리기 · 색이 고르면 꺼내기':p==='readyToEat'?'마음에 들면 한 입! 조금 더 구워도 좋아요':'Space로 돌리기 · ← → 거리 · Enter로 시작/꺼내기 · Esc 나가기';s.view.update(a,s.rotating);s.root.dataset.phase=p;
 }
 function close(token=live){if(!live||token!==live)return;const s=live;live=null;clear(s);for(const[n,t,f,o]of s.listeners)n?.removeEventListener(t,f,o);try{s.view.dispose();}finally{s.root.remove();stage.classList.remove('marshmallow-open');doc.body?.classList.remove('marshmallow-open');onActive(false);if(!doc.hidden)doc.querySelector?.('#scene')?.focus?.({preventScroll:true});}}
 function pause(s=live){if(!s||s!==live)return;clear(s);s.paused=true;render(s);}
 function action(s){if(live!==s||doc.hidden)return;if(s.paused){clear(s);s.paused=false;}else{clear(s);const type={ready:'START',roasting:'WITHDRAW',readyToEat:'EAT',done:'RETRY'}[s.state.phase];if(type)s.state=stepMarshmallow(s.state,{type});}render(s);}
 function open(){if(live||doc.hidden||!isAllowed()||getRoom?.()!=='courtyard'||!getView?.()?.root)return false;const actors=getActors?.(),p=actors?.player?.position;if(!p||Math.hypot(p.x-PLAZA.fire.x,p.z-PLAZA.fire.z)>4.5){ui.toast?.('모닥불 옆으로 조금 더 와 주세요');return false;}const root=doc.createElement('div');root.className='marsh-overlay';root.innerHTML=MARSHMALLOW_BODY;root.setAttribute('role','group');root.setAttribute('aria-label','마시멜로 굽기');stage.appendChild(root);let s;
 try{const view=createView({...actors,zoneRoot:getView().root,reduced});s={root,view,state:initialMarshmallow(),paused:false,rotating:false,pointer:null,key:null,listeners:[],fit:null,status:''};live=s;stage.classList.add('marshmallow-open');doc.body?.classList.add('marshmallow-open');onActive(true);const $=q=>root.querySelector(q),rotate=$('[data-marsh-rotate]'),main=$('[data-marsh-main]');
 listen(s,$('[data-marsh-close]'),'click',()=>close(s));listen(s,main,'click',()=>action(s));listen(s,$('[data-marsh-pause]'),'click',()=>pause(s));listen(s,$('[data-marsh-return]'),'click',()=>{if(live!==s||s.paused)return;s.state=stepMarshmallow(s.state,{type:'RETURN'});clear(s);render(s);});listen(s,$('[data-marsh-distance]'),'input',e=>{if(live!==s||s.paused)return;s.state=stepMarshmallow(s.state,{type:'DISTANCE',value:Number(e.target.value)/100});render(s);});
 listen(s,rotate,'pointerdown',e=>{if(live!==s||e.button!==0||e.isPrimary===false||s.pointer!==null||s.key||s.paused||s.state.phase!=='roasting')return;e.preventDefault();s.pointer=e.pointerId;s.rotating=true;rotate.setPointerCapture?.(e.pointerId);render(s);});
 for(const type of ['pointerup','pointercancel','lostpointercapture'])listen(s,rotate,type,e=>{if(live!==s||s.pointer!==e.pointerId)return;s.pointer=null;s.rotating=false;if(type!=='pointerup')pause(s);else render(s);});
 // Assistive technology can toggle rotation with a synthetic click; pointer
 // clicks have detail > 0 and never double-toggle after hold-and-release.
 listen(s,rotate,'click',e=>{if(live!==s||e.detail!==0||s.key||s.pointer!==null||s.paused||s.state.phase!=='roasting')return;s.rotating=!s.rotating;render(s);});
 listen(s,doc,'keydown',e=>{if(live!==s||e.ctrlKey||e.altKey||e.metaKey)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(!e.repeat)close(s);return;}const target=e.target?.tagName;if(target==='BUTTON'&&e.repeat&&['Enter','Space'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();return;}if(target==='INPUT'||target==='BUTTON')return;if(!['Space','Enter','ArrowLeft','ArrowRight'].includes(e.code))return;e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;if(e.code==='Enter'){action(s);return;}if(s.paused)return;if(e.code==='Space'&&s.state.phase==='roasting'&&s.pointer===null){s.key=e.code;s.rotating=true;}else if(['ArrowLeft','ArrowRight'].includes(e.code)&&['ready','roasting'].includes(s.state.phase))s.state=stepMarshmallow(s.state,{type:'DISTANCE',value:s.state.distance+(e.code==='ArrowLeft'?-.1:.1)});render(s);},true);
 listen(s,doc,'keyup',e=>{if(live!==s||s.key!==e.code)return;e.preventDefault();e.stopImmediatePropagation();s.key=null;s.rotating=false;render(s);},true);listen(s,win,'blur',()=>pause(s));listen(s,doc,'visibilitychange',()=>{if(doc.hidden)pause(s);});listen(s,win,'resize',()=>{if(live!==s)return;clear(s);s.fit=null;render(s);});render(s);$('[data-marsh-court]').focus?.({preventScroll:true});return true;
 }catch(error){if(s&&live===s)close(s);else root.remove();ui.toast?.('꼬치를 준비하지 못했어요. 다시 열어 주세요');return false;}}
 return {open,close:()=>close(),cancel:()=>close(),pause,get active(){return !!live;},get camera(){return live?.view.camera;},snapshot:()=>live?{...live.state,browning:[...live.state.browning],rotating:live.rotating,paused:live.paused,result:marshmallowResult(live.state)}:null,tick(dt,{paused=false}={}){const s=live;if(!s)return;if(getRoom?.()!=='courtyard'){close(s);return;}if(paused){if(!s.paused)pause(s);return;}if(s.paused||doc.hidden)return;s.state=stepMarshmallow(s.state,{type:'TICK',dt,rotate:s.rotating});render(s);},viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=live.root.querySelector('[data-marsh-court]').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,b.left-base.left),y=Math.max(0,b.top-base.top),r={x,y,width:Math.max(1,Math.min(b.width,width-x)),height:Math.max(1,Math.min(b.height,height-y))},key=JSON.stringify(r);if(key!==live.fit){live.fit=key;live.view.fit(r.width,r.height);}return r;}};
}
